const staticData = $getWorkflowStaticData('global');
const config = $('Configuration Tado').first().json;

const CLIENT_ID = config.CLIENT_ID;
const REFRESH_TOKEN = staticData.tado_refresh_token;

if (!REFRESH_TOKEN) {
  return [{
    auth_ok: false,
    auth_reason: 'missing_refresh_token'
  }];
}

try {
  const authResponse = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://login.tado.com/oauth2/token',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded',
    },
    body: `client_id=${encodeURIComponent(CLIENT_ID)}&grant_type=refresh_token&refresh_token=${encodeURIComponent(REFRESH_TOKEN)}`,
  });

  if (!authResponse.access_token) {
    return [{
      auth_ok: false,
      auth_reason: 'no_access_token_returned'
    }];
  }

  staticData.tado_access_token = authResponse.access_token;

  if (authResponse.refresh_token) {
    staticData.tado_refresh_token = authResponse.refresh_token;
  }

  return [{
    auth_ok: true,
    access_token: authResponse.access_token
  }];

} catch (error) {
  return [{
    auth_ok: false,
    auth_reason: 'refresh_failed',
    auth_error: error.message
  }];
}

// Mode: Run Once for All Items.
// "Lire météo": 5 Day Forecast, Metric (Celsius).
// Keep missing measurements unknown.
// A failed weather request must not disable indoor control.

const store = $getWorkflowStaticData('global');
const housing = $('Configuration Logement').first().json;
const config = $('Configuration Tado').first().json;
const tadoResponse = $('Lire état zone Tado').first().json;
const now = Date.now();
const HOUR = 3600000;

const key = `${config.HOME_ID}:${config.ZONE_ID}`;

store.climate_v2 ??= {};
const state = store.climate_v2[key] ??= {};

function number(value, min, max) {
  if (
    !['number', 'string'].includes(typeof value) ||
    String(value).trim() === ''
  ) {
    return null;
  }

  const n = Number(String(value).replace(',', '.'));

  return Number.isFinite(n) && n >= min && n <= max ? n : null;
}

function timestamp(value) {
  if (
    !['number', 'string'].includes(typeof value) ||
    String(value).trim() === ''
  ) {
    return null;
  }

  const raw = String(value).trim();

  if (/^\d+(?:\.\d+)?$/.test(raw)) {
    const n = Number(raw);
    return Number.isFinite(n) ? (n < 1e11 ? n * 1000 : n) : null;
  }

  // OpenWeatherMap dt_txt is UTC even without a timezone suffix.
  const normalized = /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(raw)
    ? raw.replace(' ', 'T') + 'Z'
    : raw;

  const parsed = Date.parse(normalized);

  return Number.isFinite(parsed) ? parsed : null;
}

const maxSensorAge = number(
  housing.SENSOR_MAX_AGE_MINUTES,
  5,
  1440
) ?? 90;

const maxWeatherAge = number(
  housing.WEATHER_MAX_AGE_MINUTES,
  5,
  1440
) ?? 120;

const maxForecastAge = number(
  housing.FORECAST_MAX_AGE_MINUTES,
  30,
  720
) ?? 180;

const fresh = (ts, age) =>
  ts !== null &&
  ts <= now + 300000 &&
  now - ts <= age * 60000;

// Read and validate indoor measurements.
const tado = tadoResponse.body ?? tadoResponse;

const apiOk =
  !tadoResponse.error &&
  !tado.error &&
  !(Number(tadoResponse.statusCode) >= 400) &&
  !!tado.sensorDataPoints &&
  !['OFFLINE', 'DISCONNECTED'].includes(
    String(tado.link?.state).toUpperCase()
  );

const inside = tado.sensorDataPoints?.insideTemperature;
const humidity = tado.sensorDataPoints?.humidity;

const insideTs = timestamp(inside?.timestamp);
const humidityTs = timestamp(humidity?.timestamp);

const temp = number(inside?.celsius, -10, 50);
const rh = number(humidity?.percentage, 1, 100);

// Older API payloads sometimes omit timestamps.
// The successful read is then the only available time reference.
const tempValid =
  apiOk &&
  temp !== null &&
  (insideTs === null || fresh(insideTs, maxSensorAge));

const humidityValid =
  apiOk &&
  rh !== null &&
  (humidityTs === null || fresh(humidityTs, maxSensorAge));

// Forecast timestamps describe the future, not observation times.
// Cache age is measured from the successful fetch.
const weatherItems = $('Lire météo').all().map(item => item.json ?? {});
const rawForecast = [];

let currentWeather = null;
let forecastCity = null;

function normalizeForecast(rows) {
  const points = new Map();

  for (const row of rows) {
    if (!row || typeof row !== 'object') continue;

    const ts = timestamp(row.dt) ?? timestamp(row.dt_txt);
    const temperature = number(row.main?.temp, -60, 60);

    if (
      ts === null ||
      temperature === null ||
      ts < now - 3 * HOUR ||
      ts > now + 120 * HOUR
    ) {
      continue;
    }

    points.set(ts, {
      ts,
      temp: temperature,
      humidity: number(row.main?.humidity, 1, 100),
      clouds: number(row.clouds?.all, 0, 100),
      wind: number(row.wind?.speed, 0, 80),
      rain_probability: number(row.pop, 0, 1),

      description: typeof row.weather?.[0]?.description === 'string'
        ? row.weather[0].description
        : 'indisponible',

      condition: typeof row.weather?.[0]?.main === 'string'
        ? row.weather[0].main
        : 'Unknown'
    });
  }

  return [...points.values()].sort((a, b) => a.ts - b.ts);
}

for (const response of weatherItems) {
  const weather = response.body ?? response;

  if (
    !weather ||
    typeof weather !== 'object' ||
    response.error ||
    weather.error ||
    Number(response.statusCode) >= 400 ||
    (weather.cod !== undefined && String(weather.cod) !== '200')
  ) {
    continue;
  }

  if (Array.isArray(weather.list)) {
    rawForecast.push(...weather.list);
    forecastCity = weather.city ?? forecastCity;
  } else if (Array.isArray(weather)) {
    rawForecast.push(...weather);
  } else if (
    weather.dt_txt !== undefined ||
    weather.sys?.pod !== undefined ||
    weatherItems.length > 1 ||
    timestamp(weather.dt) > now + 300000
  ) {
    rawForecast.push(weather);
  } else if (
    number(weather.main?.temp, -60, 60) !== null &&
    fresh(timestamp(weather.dt), maxWeatherAge)
  ) {
    currentWeather = weather;
  }
}

const incomingForecast = normalizeForecast(rawForecast);

let forecastSource = 'unavailable';

if (incomingForecast.some(point => point.ts >= now)) {
  state.forecast = {
    points: incomingForecast,
    fetchedAt: now,
    city: forecastCity
  };

  forecastSource = 'live';
} else if (
  state.forecast &&
  fresh(
    number(state.forecast.fetchedAt, 0, 1e15),
    maxForecastAge
  )
) {
  forecastSource = 'cached';
}

let forecast = forecastSource === 'unavailable'
  ? []
  : (Array.isArray(state.forecast.points) ? state.forecast.points : [])
      .filter(point =>
        point &&
        Number.isFinite(point.ts) &&
        Number.isFinite(point.temp) &&
        point.temp >= -60 &&
        point.temp <= 60 &&
        point.ts >= now - 3 * HOUR &&
        point.ts <= now + 120 * HOUR
      )
      .sort((a, b) => a.ts - b.ts);

if (!forecast.some(point => point.ts >= now)) {
  forecast = [];
  forecastSource = 'unavailable';
}

const nearestForecast = forecast
  .filter(point => Math.abs(point.ts - now) <= 3 * HOUR)
  .reduce(
    (best, point) =>
      best === null || Math.abs(point.ts - now) < Math.abs(best.ts - now)
        ? point
        : best,
    null
  );

let weatherSource = 'unavailable';
let meteo = {};

if (currentWeather !== null) {
  state.weather = {
    value: currentWeather,
    observedAt: timestamp(currentWeather.dt)
  };

  weatherSource = 'current';
  meteo = currentWeather;
} else if (
  state.weather &&
  fresh(state.weather.observedAt, maxWeatherAge) &&
  number(state.weather.value?.main?.temp, -60, 60) !== null
) {
  weatherSource = 'cached';
  meteo = state.weather.value;
} else if (nearestForecast !== null) {
  weatherSource = forecastSource === 'live'
    ? 'forecast_estimate'
    : 'cached_forecast_estimate';

  meteo = {
    main: {
      temp: nearestForecast.temp,
      humidity: nearestForecast.humidity
    },
    clouds: {
      all: nearestForecast.clouds
    },
    wind: {
      speed: nearestForecast.wind
    },
    weather: [{
      description: nearestForecast.description,
      main: nearestForecast.condition
    }],
    sys: {
      sunset: state.forecast.city?.sunset
    }
  };
}

const forecastEstimate = weatherSource.endsWith('forecast_estimate');

const forecastFetchTs = forecastSource === 'unavailable'
  ? null
  : state.forecast.fetchedAt;

// Interpret native Tado window signals.
function windowFlag(value) {
  if (typeof value === 'boolean') return value;
  if (value === 'true') return true;
  if (value === 'false') return false;
  if (!value || typeof value !== 'object') return null;

  const expiry = timestamp(value.expiry ?? value.expiresAt ?? value.end);

  if (expiry !== null && expiry <= now) return false;

  for (const field of ['detected', 'isOpen', 'open', 'active']) {
    if (typeof value[field] === 'boolean') return value[field];
  }

  if (['CLOSED', 'INACTIVE'].includes(value.state)) return false;
  if (['OPEN', 'ACTIVE'].includes(value.state)) return true;
  if (expiry !== null) return expiry > now;

  const detectedAt = timestamp(value.detectedTime ?? value.detectedAt);
  const duration = number(value.durationInSeconds, 1, 86400);

  if (detectedAt !== null && duration !== null) {
    return detectedAt <= now && now < detectedAt + duration * 1000;
  }

  // Settings objects, empty objects and undated events are not proof of an open window.
  return null;
}

const flag = windowFlag(tado.openWindowDetected);
const overlayFlag = windowFlag(tado.openWindow);

let windowOpen = null;

if (apiOk) {
  if (flag === true || overlayFlag === true) {
    windowOpen = true;
  } else if (
    flag === false ||
    overlayFlag === false ||
    tado.openWindow === null
  ) {
    windowOpen = false;
  }
}

const geo = ['HOME', 'AWAY'].includes(tado.geolocationOverride)
  ? tado.geolocationOverride
  : tado.tadoMode;

return [{
  json: {
    zone_key: key,
    fetched_at: now,

    temp_interieure: tempValid ? temp : null,
    humidite_interieure: humidityValid ? rh : null,
    temperature_sample_ts: tempValid ? insideTs ?? now : null,
    humidity_sample_ts: humidityValid ? humidityTs ?? now : null,

    consigne_actuelle: number(tado.setting?.temperature?.celsius, 0, 40),

    power_actuel: ['ON', 'OFF'].includes(tado.setting?.power)
      ? tado.setting.power
      : 'UNKNOWN',

    tado_api_ok: apiOk,
    presence: geo === 'HOME' ? true : geo === 'AWAY' ? false : null,

    heating_power_percent: number(
      tado.activityDataPoints?.heatingPower?.percentage,
      0,
      100
    ),

    window_open_detected: windowOpen,

    window_event_ts: timestamp(
      tado.openWindow?.detectedTime ??
      tado.openWindowDetected?.detectedTime
    ),

    temp_exterieure: number(meteo.main?.temp, -60, 60),
    humidite_pourcent: number(meteo.main?.humidity, 1, 100),
    nuages_pourcent: number(meteo.clouds?.all, 0, 100),
    vitesse_vent_ms: number(meteo.wind?.speed, 0, 80),

    condition_meteo: meteo.weather?.[0]?.description ?? 'indisponible',
    condition_meteo_main: meteo.weather?.[0]?.main ?? 'Unknown',
    sunset_ts: timestamp(meteo.sys?.sunset),

    previsions_meteo: forecast,

    quality: {
      indoor_valid: tempValid,
      humidity_valid: humidityValid,

      sensor_timestamps_available:
        insideTs !== null && humidityTs !== null,

      tado_rate_limit: tadoResponse.headers?.ratelimit ?? null,

      weather_source: weatherSource,
      weather_is_forecast_estimate: forecastEstimate,

      weather_forecast_offset_hours: forecastEstimate
        ? Number(((nearestForecast.ts - now) / HOUR).toFixed(2))
        : null,

      weather_age_minutes: weatherSource === 'unavailable'
        ? null
        : Math.max(
            0,
            Math.round(
              (
                now -
                (
                  forecastEstimate
                    ? forecastFetchTs
                    : state.weather.observedAt
                )
              ) / 60000
            )
          ),

      forecast_source: forecastSource,
      forecast_fetched_at: forecastFetchTs,

      forecast_age_minutes: forecastFetchTs === null
        ? null
        : Math.max(0, Math.round((now - forecastFetchTs) / 60000)),

      forecast_count: forecast.length,
      forecast_until: forecast.length ? forecast.at(-1).ts : null
    }
  }
}];

// Requires the updated "Fusionner données" node from the provided workflow.
// Supervisory room setpoints: Tado keeps control of the radiator valve.
// No external modules, no network calls, and no OFF command.

const store = $getWorkflowStaticData('global');
const data = $json;
const config = $('Configuration Logement').first().json;
const now = Date.now();
const MINUTE = 60000;
const HOUR = 60 * MINUTE;

store.climate_v2 ??= {};
const state = store.climate_v2[data.zone_key] ??= {};

function numeric(value) {
  if (!['number', 'string'].includes(typeof value) || String(value).trim() === '') return null;
  const n = Number(String(value).replace(',', '.'));
  return Number.isFinite(n) ? n : null;
}

const clamp = (n, min, max) => Math.min(max, Math.max(min, n));
const setting = (name, fallback, min, max) => clamp(numeric(config[name]) ?? fallback, min, max);
const enabled = (name, fallback) => typeof config[name] === 'boolean' ? config[name] : fallback;
const rounded = (n, digits = 2) => n === null || !Number.isFinite(n) ? null : Number(n.toFixed(digits));

const indoor = numeric(data.temp_interieure);
const outdoor = numeric(data.temp_exterieure);
const humidity = numeric(data.humidite_interieure);
const outsideHumidity = numeric(data.humidite_pourcent);
const current = numeric(data.consigne_actuelle);
const power = data.power_actuel;

const insideOk = data.tado_api_ok === true && indoor !== null && indoor >= -10 && indoor <= 50;
const humidityOk = data.tado_api_ok === true && humidity !== null && humidity > 0 && humidity <= 100;
const presence = typeof data.presence === 'boolean' ? data.presence : enabled('DEFAULT_PRESENCE', true);

const minSetpoint = setting('Min_thérmostat', 6, 6, 25);
const maxSetpoint = Math.max(minSetpoint, setting('Max_thérmostat', 25, 6, 25));

const allowed = [];

for (let n = 6; n <= 14; n++) {
  if (n >= minSetpoint && n <= maxSetpoint) allowed.push(n);
}

for (let n = 15; n <= 25; n += 0.5) {
  if (n >= minSetpoint && n <= maxSetpoint) allowed.push(n);
}

if (!allowed.length) {
  throw new Error('Aucun palier Tado autorisé entre les limites configurées.');
}

const quantize = value => allowed.reduce(
  (best, n) => Math.abs(n - value) < Math.abs(best - value) - 1e-9 ? n : best,
  allowed[0]
);

const eco = allowed[0];
const timezone = String(config.TIMEZONE ?? 'Europe/Paris');

const clock = new Intl.DateTimeFormat('en-GB', {
  timeZone: timezone,
  year: 'numeric',
  month: 'numeric',
  day: 'numeric',
  hour: 'numeric',
  minute: 'numeric',
  weekday: 'short',
  hourCycle: 'h23'
});

function localContext(ts) {
  const p = Object.fromEntries(
    clock.formatToParts(new Date(ts)).map(p => [p.type, p.value])
  );

  const month = Number(p.month);
  const hour = Number(p.hour) + Number(p.minute) / 60;
  const weekend = p.weekday === 'Sat' || p.weekday === 'Sun';

  const morning = setting(
    weekend ? 'WEEKEND_MORNING_HOUR' : 'WORKDAY_MORNING_HOUR',
    weekend ? 8 : 6,
    0,
    12
  );

  const evening = setting('EVENING_START_HOUR', 17, 12, 22);
  const night = setting('NIGHT_START_HOUR', 22, evening, 23.5);
  const lateNight = setting('LATE_NIGHT_START_HOUR', 23, night, 24);

  const phase = hour < morning || hour >= lateNight
    ? 'late_night'
    : hour < 9
      ? 'morning'
      : hour < evening
        ? 'day'
        : hour < night
          ? 'evening'
          : 'night';

  const season = [12, 1, 2].includes(month)
    ? 'winter'
    : [3, 4, 5].includes(month)
      ? 'spring'
      : [6, 7, 8].includes(month)
        ? 'summer'
        : 'autumn';

  return { month, hour, weekend, phase, season };
}

const context = localContext(now);

const comfortTable = {
  winter: {
    late_night: 18,
    morning: 21.2,
    day: 21.5,
    evening: 21.5,
    night: 19
  },
  spring: {
    late_night: 17.8,
    morning: 20.8,
    day: 21,
    evening: 21,
    night: 18.7
  },
  summer: {
    late_night: 17.5,
    morning: 20,
    day: 20.5,
    evening: 20.5,
    night: 18
  },
  autumn: {
    late_night: 18,
    morning: 21,
    day: 21.2,
    evening: 21.2,
    night: 18.8
  }
};

const comfortOffset = setting('COMFORT_OFFSET_C', 0, -4, 3);
const awayTarget = setting('AWAY_TARGET_C', 17.5, 6, 22);

function comfortAt(ctx) {
  let value = comfortTable[ctx.season][ctx.phase] + comfortOffset;

  if (ctx.weekend && ctx.phase === 'morning' && ctx.season !== 'summer') {
    value += 0.2;
  }

  return presence ? clamp(value, 16, 22) : Math.min(value, awayTarget);
}

const baseComfort = comfortAt(context);

// Five rolling 24-hour periods. Only the next few hours may initiate an adjustment.
// More distant days can strengthen that immediate signal, but cannot trigger it alone.
const forecastEnabled = enabled('FORECAST_ENABLED', true);
const forecastFetchTs = numeric(data.quality?.forecast_fetched_at);

const forecastFresh = forecastFetchTs !== null &&
  forecastFetchTs <= now + 5 * MINUTE &&
  now - forecastFetchTs <= setting('FORECAST_MAX_AGE_MINUTES', 180, 30, 720) * MINUTE;

const forecastMap = new Map();

if (forecastEnabled && forecastFresh && Array.isArray(data.previsions_meteo)) {
  for (const point of data.previsions_meteo) {
    const ts = numeric(point?.ts);
    const temp = numeric(point?.temp);

    if (
      ts !== null &&
      ts >= now &&
      ts <= now + 120 * HOUR &&
      temp !== null &&
      temp >= -60 &&
      temp <= 60
    ) {
      forecastMap.set(ts, { ts, temp });
    }
  }
}

const forecastPoints = [...forecastMap.values()].sort((a, b) => a.ts - b.ts);

function forecastPeriod(startHours, endHours, inclusiveEnd = false) {
  const start = now + startHours * HOUR;
  const end = now + endHours * HOUR;

  const points = forecastPoints.filter(point =>
    point.ts >= start &&
    (inclusiveEnd || endHours === 120 ? point.ts <= end : point.ts < end)
  );

  const temperatures = points.map(point => point.temp);

  const continuous =
    points.length >= Math.max(2, Math.floor((endHours - startHours) / 3) - 1) &&
    points[0].ts <= start + 3 * HOUR &&
    points.at(-1).ts >= end - 3 * HOUR &&
    points.every((point, index) =>
      index === 0 || point.ts - points[index - 1].ts <= 3.1 * HOUR
    );

  return {
    count: points.length,
    complete: continuous,
    mean: points.length
      ? temperatures.reduce((a, b) => a + b, 0) / points.length
      : null,
    min: points.length ? Math.min(...temperatures) : null,
    max: points.length ? Math.max(...temperatures) : null
  };
}

const forecastHorizon = setting('FORECAST_HORIZON_HOURS', 6, 6, 12);
const nearForecast = forecastPeriod(0, forecastHorizon, true);
const dayForecast = forecastPeriod(0, 24);

const forecastDays = Array.from({ length: 5 }, (_, index) => ({
  day: index + 1,
  from_hours: index * 24,
  to_hours: (index + 1) * 24,
  ...forecastPeriod(index * 24, (index + 1) * 24)
}));

const dayWeights = [1, 0.65, 0.4, 0.25, 0.15];
const usableDays = forecastDays.filter(day => day.complete);

const totalWeight = usableDays.reduce(
  (sum, day) => sum + dayWeights[day.day - 1],
  0
);

const forecastMean5d = totalWeight > 0
  ? usableDays.reduce(
      (sum, day) => sum + day.mean * dayWeights[day.day - 1],
      0
    ) / totalWeight
  : null;

const forecastReady =
  forecastEnabled &&
  forecastFresh &&
  nearForecast.complete &&
  outdoor !== null;

const nearDelta = forecastReady ? nearForecast.mean - outdoor : null;

const warmingSoon =
  forecastReady &&
  nearForecast.min >= setting('FORECAST_MILD_MIN_C', 16, 10, 22) &&
  (nearDelta >= 2 || nearForecast.mean >= baseComfort - 1);

const coolingSoon =
  forecastReady &&
  nearDelta <= -3 &&
  nearForecast.min <= 8;

let forecastReduction = 0;
let forecastBoost = 0;

let forecastReason = !forecastEnabled
  ? 'desactivees'
  : !forecastReady
    ? 'previsions_insuffisantes'
    : 'maintien';

// Estimate the measured trend from distinct sensor samples, not from execution count.
const historyWindow = setting('TREND_WINDOW_MINUTES', 120, 30, 240) * MINUTE;

state.history = (Array.isArray(state.history) ? state.history : []).filter(p =>
  Number.isFinite(p.ts) &&
  Number.isFinite(p.temp) &&
  p.ts <= now + MINUTE &&
  p.ts >= now - historyWindow
);

const sampleTs = numeric(data.temperature_sample_ts);

if (
  insideOk &&
  sampleTs !== null &&
  !state.history.some(p => p.ts === sampleTs)
) {
  state.history.push({
    ts: sampleTs,
    temp: indoor,
    window: data.window_open_detected === true
  });
}

state.history.sort((a, b) => a.ts - b.ts);
state.history = state.history.slice(-64);

const trendPoints = state.history.filter(p =>
  !p.window && p.ts > (state.window?.lastClearedAt ?? 0)
);

let trend = null;

if (
  trendPoints.length >= 3 &&
  trendPoints.at(-1).ts - trendPoints[0].ts >= 30 * MINUTE
) {
  const meanX = trendPoints.reduce(
    (sum, p) => sum + (p.ts - now) / HOUR,
    0
  ) / trendPoints.length;

  const meanY = trendPoints.reduce(
    (sum, p) => sum + p.temp,
    0
  ) / trendPoints.length;

  let covariance = 0;
  let variance = 0;

  for (const p of trendPoints) {
    const dx = (p.ts - now) / HOUR - meanX;
    covariance += dx * (p.temp - meanY);
    variance += dx * dx;
  }

  if (variance > 0) {
    trend = clamp(covariance / variance, -2, 2);
  }
}

// Low-order astronomical estimate.
// Vertical-window incidence is an estimate, not measured solar heat.
function solarPosition() {
  const lat = numeric(config.Lat);
  const lon = numeric(config.Lon);

  if (
    lat === null ||
    lon === null ||
    Math.abs(lat) > 90 ||
    Math.abs(lon) > 180
  ) {
    return null;
  }

  const rad = Math.PI / 180;
  const days = now / 86400000 - 10957.5;
  const g = (357.528 + 0.9856003 * days) * rad;

  const lambda = (
    280.460 +
    0.9856474 * days +
    1.915 * Math.sin(g) +
    0.020 * Math.sin(2 * g)
  ) * rad;

  const epsilon = (23.439 - 0.0000004 * days) * rad;

  const alpha = Math.atan2(
    Math.cos(epsilon) * Math.sin(lambda),
    Math.cos(lambda)
  );

  const delta = Math.asin(Math.sin(epsilon) * Math.sin(lambda));

  const h = (
    (18.697374558 + 24.06570982441908 * days) * 15 + lon
  ) * rad - alpha;

  const phi = lat * rad;

  const elevation = Math.asin(
    Math.sin(phi) * Math.sin(delta) +
    Math.cos(phi) * Math.cos(delta) * Math.cos(h)
  );

  const azimuth = (
    Math.atan2(
      Math.sin(h),
      Math.cos(h) * Math.sin(phi) - Math.tan(delta) * Math.cos(phi)
    ) / rad + 540
  ) % 360;

  return { elevation: elevation / rad, azimuth };
}

const solar = solarPosition();
const clouds = numeric(data.nuages_pourcent);
const wind = numeric(data.vitesse_vent_ms);

let solarScore = 0;

if (solar && clouds !== null && solar.elevation > 5) {
  const difference = Math.abs(
    ((solar.azimuth - setting('AZIMUTH', 285, 0, 360) + 540) % 360) - 180
  );

  if (difference <= setting('AZIMUTH_TOLERANCE', 45, 0, 90)) {
    solarScore =
      Math.cos(solar.elevation * Math.PI / 180) *
      Math.cos(difference * Math.PI / 180) *
      (1 - clamp(clouds / 100, 0, 1));
  }
}

let weatherCorrection = 0;

if (
  outdoor !== null &&
  presence &&
  !['night', 'late_night'].includes(context.phase)
) {
  weatherCorrection = outdoor < 8
    ? clamp((8 - outdoor) / 20, 0, 0.5)
    : -clamp((outdoor - 16) / 12, 0, 0.5);

  if (outdoor < 8 && wind !== null) {
    weatherCorrection += clamp((wind - 4) / 40, 0, 0.15);
  }

  weatherCorrection = clamp(weatherCorrection, -0.5, 0.5);
}

let comfort = clamp(
  baseComfort + weatherCorrection,
  eco,
  Math.min(22, maxSetpoint)
);

// Anticipation is confined to a forthcoming higher schedule target.
const future = localContext(
  now + setting('PREHEAT_MINUTES', 45, 0, 90) * MINUTE
);

let preheating = false;

if (
  insideOk &&
  presence &&
  future.phase !== context.phase &&
  comfortAt(future) > baseComfort &&
  indoor < comfortAt(future) - 0.5 &&
  (outdoor === null || outdoor < 16)
) {
  comfort = clamp(comfortAt(future), eco, Math.min(22, maxSetpoint));
  preheating = true;
}

// A measured comfort deficit or cooling room always cancels forecast savings.
const dayPhase = !['night', 'late_night'].includes(context.phase);
const gentleCoolingLimit = -0.15;

const canReduceFromForecast =
  insideOk &&
  !preheating &&
  indoor >= comfort - 0.3 &&
  (trend === null || trend >= gentleCoolingLimit);

if (warmingSoon && canReduceFromForecast) {
  const sustainedMild = forecastMean5d !== null && forecastMean5d >= 16;

  const strength = clamp(
    Math.max(nearDelta / 6, (nearForecast.mean - 16) / 6),
    0.25,
    1
  );

  forecastReduction =
    setting('FORECAST_MAX_REDUCTION_C', 0.5, 0, 1) *
    strength *
    (sustainedMild ? 1 : 0.75);

  forecastReason = 'redoux_proche_piece_assez_chaude';
} else if (
  coolingSoon &&
  insideOk &&
  presence &&
  dayPhase &&
  !preheating &&
  (
    indoor < comfort - 0.3 ||
    (trend !== null && trend < -0.1 && indoor <= comfort + 0.2)
  )
) {
  const sustainedCold = forecastMean5d !== null && forecastMean5d < 8;

  forecastBoost =
    setting('FORECAST_MAX_BOOST_C', 0.5, 0, 0.5) *
    clamp(-nearDelta / 6, 0, 1) *
    (sustainedCold ? 1 : 0.75);

  // Keep the combined present-weather and forecast cold correction at or below +0.5 C.
  forecastBoost = Math.min(
    forecastBoost,
    Math.max(0, 0.5 - Math.max(0, weatherCorrection))
  );

  const originalComfort = comfort;

  comfort = clamp(
    comfort + forecastBoost,
    eco,
    Math.min(22, maxSetpoint)
  );

  forecastBoost = comfort - originalComfort;
  forecastReason = 'refroidissement_proche_besoin_mesure';
} else if (warmingSoon && !canReduceFromForecast) {
  forecastReason = 'redoux_annonce_mais_confort_prioritaire';
}

// ECO needs mild weather over 24 h, a warm room and a measured stable/rising trend.
// Hysteresis uses the previous successful command, not a merely computed decision.
const wasForecastEco =
  state.lastApplied?.mode === 'FORECAST_MILD_ECO' &&
  current === eco &&
  power === 'ON';

const forecastEco =
  forecastReady &&
  dayForecast.complete &&
  nearForecast.mean >= baseComfort - 1 &&
  dayForecast.min >= setting('FORECAST_ECO_MIN_C', 18, 16, 22) &&
  insideOk &&
  !preheating &&
  trend !== null &&
  trend >= (wasForecastEco ? -0.1 : 0) &&
  indoor >= comfort + (wasForecastEco ? 0.1 : 0.5);

const inertia = setting('THERMAL_INERTIA', 0.9, 0, 1);
const reductionLimit = setting('MAX_SOLAR_REDUCTION_C', 0.5, 0, 1);

const solarReduction =
  insideOk &&
  indoor >= comfort - 0.3 &&
  trend !== null &&
  trend > 0.1
    ? solarScore * reductionLimit * inertia
    : 0;

const trendReduction =
  insideOk &&
  indoor >= comfort - 0.2 &&
  trend !== null
    ? clamp(trend * (20 / 60) * inertia, 0, reductionLimit)
    : 0;

// Do not count the same measured warming twice as both trend and solar heat.
let requested = comfort - Math.max(
  solarReduction,
  trendReduction,
  forecastReduction
);

let targetMode = preheating ? 'PREHEAT' : presence ? 'COMFORT' : 'AWAY';
let reason = preheating ? 'anticipation_horaire' : 'consigne_confort_stable';

if (forecastReduction > 0) {
  targetMode = 'FORECAST_REDUCED';
  reason = forecastReason;
} else if (forecastBoost > 0) {
  targetMode = 'FORECAST_COLD';
  reason = forecastReason;
}

// Window episodes use only the native Tado signal.
// Its disappearance is not proof of physical closure.
state.window ??= { active: false };

const window = state.window;
const wasWindowActive = window.active === true;
const nativeWindow = data.window_open_detected;

if (data.tado_api_ok && nativeWindow === true) {
  if (!window.active) {
    window.openedAt = now;
    window.episodeId = `${now}`;
  }

  window.active = true;
  window.lastPositiveAt = now;
  window.lastKnownAt = now;
} else if (data.tado_api_ok && nativeWindow === false) {
  window.lastKnownAt = now;

  if (
    window.active &&
    now - window.openedAt >= setting('WINDOW_HOLD_MINUTES', 15, 0, 60) * MINUTE
  ) {
    window.active = false;
    window.lastClearedAt = now;
  }
} else if (
  window.active &&
  now - (window.lastPositiveAt ?? 0) >
    setting('WINDOW_UNKNOWN_HOLD_MINUTES', 60, 15, 180) * MINUTE
) {
  window.active = false;
  window.lastClearedAt = now;
}

const windowActive = window.active === true;
const windowJustCleared = wasWindowActive && !windowActive;
const overheatLimit = setting('OVERHEAT_LIMIT', 22.6, 19, 30);

if (insideOk) {
  state.overheat = state.overheat
    ? indoor > overheatLimit - 0.6
    : indoor >= overheatLimit;

  const warmThreshold = context.season === 'summer'
    ? 20
    : setting('HARD_SUMMER_EXT_LIMIT', 25, 18, 35);

  // A forecast estimate must meet the stricter 24-hour ECO rules above.
  // An imminent cold front also vetoes the legacy current-weather standby.
  state.warmStandby =
    data.quality?.weather_is_forecast_estimate !== true &&
    !coolingSoon &&
    outdoor !== null &&
    (
      state.warmStandby
        ? outdoor >= warmThreshold - 2 && indoor >= comfort - 0.5
        : outdoor >= warmThreshold && indoor >= comfort + 0.3
    );
}

if (windowActive) {
  requested = eco;
  targetMode = 'WINDOW_OPEN_ECO';

  reason = nativeWindow === true
    ? 'ouverture_signalee_par_tado'
    : 'temporisation_apres_signal_fenetre';
} else if (insideOk && state.overheat) {
  requested = eco;
  targetMode = 'OVERHEAT_ECO';
  reason = 'surchauffe_mesuree';
} else if (insideOk && state.warmStandby) {
  requested = eco;
  targetMode = 'WARM_WEATHER_ECO';
  reason = 'temps_doux_et_piece_deja_chaude';
} else if (forecastEco) {
  requested = eco;
  targetMode = 'FORECAST_MILD_ECO';
  reason = 'douceur_24h_et_piece_chaude_stable';
} else if (
  Math.max(solarReduction, trendReduction) > Math.max(0.1, forecastReduction)
) {
  reason = 'reduction_limitee_montee_mesuree';
}

const legacyScriptOff = store.script_turned_it_off === true && !state.lastApplied;

const externalOff =
  power === 'OFF' &&
  enabled('RESPECT_MANUAL_OFF', true) &&
  !windowActive &&
  !windowJustCleared &&
  !legacyScriptOff &&
  state.lastApplied?.mode !== 'WINDOW_OPEN_ECO';

let target = quantize(requested);

// A small deadband around each rounding boundary prevents alternating half-degree requests.
if (
  !targetMode.endsWith('_ECO') &&
  allowed.includes(current) &&
  power === 'ON' &&
  target !== current
) {
  const boundary =
    Math.abs(target - current) / 2 +
    setting('SETPOINT_DEADBAND_C', 0.1, 0, 0.25);

  if (Math.abs(requested - current) < boundary) {
    target = current;
  }
}

const lastUpdate = numeric(state.lastApplied?.ts) ?? 0;

const urgent =
  (
    windowActive &&
    (
      state.lastApplied?.mode !== 'WINDOW_OPEN_ECO' ||
      current !== eco ||
      power !== 'ON'
    )
  ) ||
  windowJustCleared ||
  (insideOk && state.overheat && current !== eco) ||
  (insideOk && indoor < 12 && !windowActive);

const delayOk =
  now - lastUpdate >= setting('MIN_DELAY_MINUTES', 25, 0, 180) * MINUTE ||
  urgent;

const targetChangedEnough =
  current === null ||
  Math.abs(target - current) >= setting('MIN_DELTA_SETPOINT', 0.5, 0.5, 2) ||
  power === 'OFF';

let action = targetChangedEnough && delayOk ? 'UPDATE' : 'IGNORE';

if (!insideOk || !['ON', 'OFF'].includes(power)) {
  action = 'IGNORE';
  reason = 'mesure_interieure_ou_etat_tado_indisponible';
  targetMode = 'DATA_UNAVAILABLE';
} else if (externalOff) {
  action = 'IGNORE';
  reason = 'etat_off_externe_respecte';
  targetMode = 'EXTERNAL_OFF_RESPECTED';
}

// Tetens vapor pressure (hPa).
// The same equation is used for RH, dew point and ventilation advice.
const saturation = temperature =>
  6.11 * 10 ** (7.5 * temperature / (237.3 + temperature));

const pressureInside = insideOk && humidityOk
  ? saturation(indoor) * humidity / 100
  : null;

const pressureOutside = outdoor !== null && outsideHumidity !== null
  ? saturation(outdoor) * outsideHumidity / 100
  : null;

function dewPoint(pressure) {
  if (pressure === null || pressure <= 0) return null;

  const a = Math.log10(pressure / 6.11);
  return 237.3 * a / (7.5 - a);
}

const dewInside = dewPoint(pressureInside);
const dewOutside = dewPoint(pressureOutside);

const equivalentOutsideRh = insideOk && pressureOutside !== null
  ? 100 * pressureOutside / saturation(indoor)
  : null;

const dryingBenefit = humidityOk && equivalentOutsideRh !== null
  ? humidity - equivalentOutsideRh
  : null;

const effectiveVentilation =
  dryingBenefit !== null &&
  dryingBenefit >= setting('VENTILATION_MIN_RH_GAIN', 5, 2, 20);

// This surface estimate is diagnostic only; it never raises the heating target.
const measuredSurface = numeric(data.temp_surface_interieure);

const surfaceTemperature = measuredSurface ?? (
  insideOk && outdoor !== null && outdoor < indoor
    ? outdoor + setting('SURFACE_FACTOR', 0.75, 0.3, 1) * (indoor - outdoor)
    : null
);

const condensationMargin =
  dewInside !== null && surfaceTemperature !== null
    ? surfaceTemperature - dewInside
    : null;

const condensationRisk =
  humidityOk &&
  condensationMargin !== null &&
  condensationMargin <= setting('CONDENSATION_MARGIN_C', 2, 0, 5);

const low = setting('HUMIDITY_LOW_PERCENT', 30, 15, 45);
const high = setting('HUMIDITY_HIGH_PERCENT', 60, 50, 80);

const criticalLow = Math.min(
  low - 2,
  setting('HUMIDITY_CRITICAL_LOW_PERCENT', 25, 5, 40)
);

const criticalHigh = Math.max(
  high + 2,
  setting('HUMIDITY_CRITICAL_HIGH_PERCENT', 70, 55, 95)
);

const hysteresis = setting('HUMIDITY_HYSTERESIS_PERCENT', 3, 1, 5);

state.humidity ??= {};
const hum = state.humidity;

let humidityStatus = 'unknown';
let humiditySeverity = 'none';

if (humidityOk) {
  humidityStatus = 'normal';

  if (
    humidity <= low ||
    (hum.status === 'too_dry' && humidity < low + hysteresis)
  ) {
    humidityStatus = 'too_dry';
  } else if (
    humidity >= high ||
    condensationRisk ||
    (hum.status === 'too_humid' && humidity > high - hysteresis)
  ) {
    humidityStatus = 'too_humid';
  }

  if (humidityStatus !== 'normal') {
    humiditySeverity = (
      humidityStatus === 'too_dry'
        ? humidity <= criticalLow ||
          (
            hum.status === 'too_dry' &&
            hum.severity === 'critical' &&
            humidity < criticalLow + 2
          )
        : humidity >= criticalHigh ||
          (
            hum.status === 'too_humid' &&
            hum.severity === 'critical' &&
            humidity > criticalHigh - 2
          )
    ) ? 'critical' : 'warning';
  }
}

const humiditySample = numeric(data.humidity_sample_ts);
const candidateKey = `${humidityStatus}:${humiditySeverity}`;

const gapTooLong =
  humiditySample !== null &&
  hum.lastSampleTs !== undefined &&
  humiditySample - hum.lastSampleTs >
    setting('SENSOR_MAX_AGE_MINUTES', 90, 5, 1440) * MINUTE;

if (!humidityOk) {
  hum.candidate = null;
  hum.count = 0;
} else if (humiditySample !== null && humiditySample !== hum.lastSampleTs) {
  if (hum.candidate !== candidateKey || gapTooLong) {
    hum.candidate = candidateKey;
    hum.since = humiditySample;
    hum.count = 1;
  } else {
    hum.count = (hum.count ?? 0) + 1;
  }

  hum.lastSampleTs = humiditySample;
  hum.status = humidityStatus;
  hum.severity = humiditySeverity;
}

const confirmMinutes = humiditySeverity === 'critical'
  ? setting('HUMIDITY_CRITICAL_CONFIRM_MINUTES', 5, 0, 60)
  : setting('HUMIDITY_CONFIRM_MINUTES', 30, 0, 180);

const confirmed =
  humidityOk &&
  hum.candidate === candidateKey &&
  hum.count >= 2 &&
  humiditySample - hum.since >= confirmMinutes * MINUTE;

const extreme = humidityOk && (humidity <= 15 || humidity >= 85);
const abnormal = !['normal', 'unknown'].includes(humidityStatus);

if (confirmed && !abnormal) {
  hum.activeEpisode = null;
}

if (
  abnormal &&
  (confirmed || extreme) &&
  (!hum.activeEpisode || hum.activeEpisode.family !== humidityStatus)
) {
  hum.activeEpisode = {
    id: `${hum.since}:${humidityStatus}`,
    family: humidityStatus
  };
}

const lastHumAlert = hum.lastSent ?? {};

const elapsedHumAlert = lastHumAlert.ts === undefined
  ? Infinity
  : now - lastHumAlert.ts;

const escalated =
  lastHumAlert.family === humidityStatus &&
  lastHumAlert.severity === 'warning' &&
  humiditySeverity === 'critical';

const newEpisode = lastHumAlert.episodeId !== hum.activeEpisode?.id;

const cooldownHours = escalated
  ? 0.5
  : newEpisode
    ? 2
    : humiditySeverity === 'critical'
      ? setting('HUMIDITY_CRITICAL_REMINDER_HOURS', 6, 1, 48)
      : setting('HUMIDITY_REMINDER_HOURS', 12, 1, 72);

const sendHumAlert =
  abnormal &&
  (confirmed || extreme) &&
  elapsedHumAlert >= cooldownHours * HOUR;

const idealRange = context.season === 'winter'
  ? '35–50 %'
  : context.season === 'summer'
    ? '40–60 %'
    : '40–55 %';

function humidityAdvice() {
  if (humidityStatus === 'too_dry') {
    const outdoorAdvice = dryingBenefit !== null && dryingBenefit > 5
      ? "L’air extérieur assécherait encore la pièce une fois réchauffé. "
      : '';

    return `${outdoorAdvice}Garde l’aération quotidienne et la ventilation habituelle, évite de surchauffer et surveille le taux avant d’humidifier davantage.`;
  }

  const storm = String(data.condition_meteo_main).toLowerCase() === 'thunderstorm';

  if (storm || (wind !== null && wind >= 12)) {
    return "Orage ou vent fort : privilégie la VMC ou l’extraction ; aère brièvement quand les conditions le permettent.";
  }

  if (nativeWindow === true && effectiveVentilation) {
    return "Tado signale déjà une ouverture. L’air extérieur peut assécher la pièce ; surveille la baisse d’humidité et évite de prolonger inutilement l’aération.";
  }

  if (effectiveVentilation) {
    const duration = outdoor <= 8 || (wind !== null && wind >= 5)
      ? '5 à 10'
      : 'environ 10';

    const rain = ['rain', 'drizzle', 'snow'].includes(
      String(data.condition_meteo_main).toLowerCase()
    )
      ? " Choisis une ouverture abritée des précipitations."
      : '';

    return `Aérer ${duration} minutes peut assécher la pièce : l’air extérieur ramené à ${rounded(indoor, 1)} °C serait à environ ${rounded(equivalentOutsideRh, 0)} % HR.${rain} Garde la ventilation habituelle.`;
  }

  if (dryingBenefit === null) {
    return "Données extérieures insuffisantes pour conseiller une aération déshumidifiante. Garde la ventilation habituelle et vérifie les sources d’humidité.";
  }

  return "L’air extérieur n’est pas assez sec pour déshumidifier efficacement par une longue aération. Garde la ventilation habituelle, utilise l’extraction et vérifie les sources d’humidité ; un déshumidificateur peut aider si cela persiste.";
}

const alertMessage = abnormal ? [
  humidityStatus === 'too_dry'
    ? `🌵 Air ${humiditySeverity === 'critical' ? 'très ' : ''}sec : ${rounded(humidity, 1)} % HR.`
    : `💧 ${condensationRisk && humidity < high ? 'Risque de condensation sur paroi froide' : humiditySeverity === 'critical' ? 'Air très humide' : 'Air humide'} : ${rounded(humidity, 1)} % HR.`,

  insideOk
    ? `Intérieur : ${rounded(indoor, 1)} °C. Repère de confort saisonnier : ${idealRange}.`
    : `Repère de confort saisonnier : ${idealRange}.`,

  condensationRisk
    ? `Point de rosée : ${rounded(dewInside, 1)} °C ; paroi ${measuredSurface === null ? 'estimée' : 'mesurée'} à ${rounded(surfaceTemperature, 1)} °C. ${measuredSurface === null ? 'Estimation à vérifier sur place.' : ''}`
    : '',

  humidityAdvice(),

  data.quality?.weather_is_forecast_estimate === true
    ? 'Météo extérieure estimée à partir des prévisions, à confirmer sur place.'
    : ''
].filter(Boolean).join('\n') : null;

// Only successful Telegram acknowledgements update lastSent.
// Failed messages remain retryable.
const windowReminder = setting('WINDOW_REMINDER_MINUTES', 60, 15, 360) * MINUTE;

const sendWindowAlert =
  data.tado_api_ok === true &&
  nativeWindow === true &&
  (
    window.lastSent?.episodeId !== window.episodeId ||
    now - window.lastSent.ts >= windowReminder
  );

const windowMessage = sendWindowAlert ? [
  window.lastSent?.episodeId === window.episodeId
    ? '🪟 Tado signale toujours une fenêtre ouverte.'
    : '🪟 Tado vient de signaler une fenêtre ouverte.',

  insideOk
    ? `Intérieur : ${rounded(indoor, 1)} °C${humidityOk ? ` · Humidité : ${rounded(humidity, 1)} %` : ''}.`
    : 'Température intérieure indisponible.',

  action === 'UPDATE'
    ? `Consigne demandée : ${target} °C, mode ON.`
    : insideOk && current === eco && power === 'ON'
      ? `Consigne actuelle : ${eco} °C, mode ON.`
      : 'Vérifie le chauffage dans Tado : aucune nouvelle consigne n’a été envoyée par cette décision.',

  'Vérifie la fenêtre. Tado déduit l’ouverture des variations de température/humidité ; ce signal ne remplace pas un capteur de contact.'
].join('\n') : null;

return [{
  json: {
    ...data,

    cible: target,
    target_mode: targetMode,
    action,
    reason,
    delayOk,
    targetChangedEnough,

    sendHumAlert,
    alertMessage,
    sendWindowAlert,
    windowMessage,

    humidity_alert_meta: sendHumAlert
      ? {
          ts: now,
          family: humidityStatus,
          severity: humiditySeverity,
          episodeId: hum.activeEpisode.id
        }
      : null,

    window_alert_meta: sendWindowAlert
      ? {
          ts: now,
          episodeId: window.episodeId
        }
      : null,

    debug_thermique: {
      timezone,
      ...context,
      presence,
      presence_source: typeof data.presence === 'boolean'
        ? 'tado'
        : 'configuration',

      confort_base: rounded(baseComfort),
      correction_meteo: rounded(weatherCorrection),
      confort_cible: rounded(comfort),
      consigne_avant_arrondi: rounded(requested),

      tendance_deg_par_heure: rounded(trend),
      echantillons_tendance: trendPoints.length,

      anticipation_horaire: preheating,
      fenetre_active: windowActive,
      surchauffe: !!state.overheat,
      temps_doux: !!state.warmStandby
    },

    debug_previsions: {
      activees: forecastEnabled,
      fraiches: forecastFresh,
      utilisables: forecastReady,
      source: data.quality?.forecast_source ?? 'unavailable',
      temperature_exterieure_estimee:
        data.quality?.weather_is_forecast_estimate === true,

      horizon_heures: forecastHorizon,
      nombre_creneaux: forecastPoints.length,

      moyenne_prochaines_heures_c: rounded(nearForecast.mean),
      minimum_prochaines_heures_c: rounded(nearForecast.min),
      ecart_prochaines_heures_c: rounded(nearDelta),
      minimum_24h_c: rounded(dayForecast.min),
      moyenne_ponderee_5j_c: rounded(forecastMean5d),

      resume_5_jours: forecastDays.map(day => ({
        jour: day.day,
        de_heures: day.from_hours,
        a_heures: day.to_hours,
        creneaux: day.count,
        couverture_suffisante: day.complete,
        moyenne_c: rounded(day.mean),
        minimum_c: rounded(day.min),
        maximum_c: rounded(day.max)
      })),

      redoux_proche: warmingSoon,
      refroidissement_proche: coolingSoon,
      reduction_c: rounded(forecastReduction),
      hausse_c: rounded(forecastBoost),
      eco_possible: forecastEco,
      motif: forecastReason,
      retenues_pour_decision: targetMode.startsWith('FORECAST_')
    },

    debug_solaire: {
      elevation: rounded(solar?.elevation),
      azimut: rounded(solar?.azimuth),
      nuages: clouds,
      gain_estime: rounded(solarScore),
      reduction_solaire_c: rounded(solarReduction),
      reduction_tendance_c: rounded(trendReduction)
    },

    debug_humidite: {
      statut: humidityStatus,
      severite: humiditySeverity,
      plage_ideale: idealRange,

      seuil_bas: low,
      seuil_haut: high,
      seuil_critique_bas: criticalLow,
      seuil_critique_haut: criticalHigh,

      point_rosee_interieur_c: rounded(dewInside),
      point_rosee_exterieur_c: rounded(dewOutside),

      humidite_absolue_interieure_g_m3: pressureInside === null
        ? null
        : rounded(216.7 * pressureInside / (indoor + 273.15)),

      humidite_absolue_exterieure_g_m3: pressureOutside === null
        ? null
        : rounded(216.7 * pressureOutside / (outdoor + 273.15)),

      humidite_exterieure_ramenee_interieur_percent:
        rounded(equivalentOutsideRh),

      gain_aeration_points_hr: rounded(dryingBenefit),
      aeration_deshumidifiante: effectiveVentilation,

      temperature_paroi_c: rounded(surfaceTemperature),
      paroi_estimee: measuredSurface === null,
      marge_condensation_c: rounded(condensationMargin),
      risque_condensation: condensationRisk,

      nombre_mesures_consecutives: hum.count ?? 0,
      confirme: confirmed,
      meteo: data.condition_meteo
    }
  }
}];

parameters.jsonBody:
={{ (() => {
  const target = $json.cible;
  const allowed = Number.isFinite(target) && target >= 6 && target <= 25 &&
    (target < 15 ? Number.isInteger(target) : Number.isInteger(target * 2));
